package com.ias.finance;
import org.junit.jupiter.api.*;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.finance.MoneyLedger.*;
import static com.ias.finance.JdbcMoneyLedger.*;

class MoneyLedgerTest {
 JdbcFeeGroupsTest fixture;JdbcMoneyLedger ledger;UUID bill,line;Approval approval;
 @BeforeEach void setup()throws Exception{fixture=new JdbcFeeGroupsTest();fixture.setup();ledger=new JdbcMoneyLedger(fixture.source,new Authority(){public void current(JdbcFeeGroups.Actor a,FeeGroup.Identity o,String action){if(!fixture.allowed.get())throw new SecurityException("DENIED");}public void verify(JdbcFeeGroups.Actor a,FeeGroup.Identity o,UUID op,Command c){if(c instanceof Reverse r&&r.reason().equals("REAL_RECEIVED_FUNDS"))throw new SecurityException("REAL_FUNDS_REQUIRE_REFUND");}});bill=UUID.randomUUID();line=UUID.randomUUID();approval=new Approval(UUID.randomUUID(),"a".repeat(64),Map.of(line,230000L));}
 Voucher voucher(String ref){return new Voucher(ref,LocalDate.of(2026,10,23),"BANK_OFFLINE",UUID.randomUUID(),"b".repeat(64));}
 Payment payment(long n,String ref){return new Payment(UUID.randomUUID(),bill,n,voucher(ref));}
 Receipt apply(UUID op,Command c)throws Exception{return ledger.apply(fixture.actor,fixture.owner,op,c);}
 Receipt apply(Command c)throws Exception{return apply(UUID.randomUUID(),c);}
 State balance()throws Exception{return ledger.read(fixture.actor,fixture.owner);}
 void assessBill()throws Exception{apply(new Assess(0,0,bill,approval));}
 void lowerBill()throws Exception{apply(new Lower(2,0,bill,line,180000,UUID.randomUUID(),"c".repeat(64),"客户确认并经财务审批的应收降低"));}
 @Test void lowerCreatesOverpaymentAndActualPartialRefundsPreserveOriginal()throws Exception{assessBill();var payment=payment(230000,"receipt-1");apply(new Collect(1,0,bill,payment));lowerBill();assertEquals(180000,balance().settled());assertEquals(50000,balance().overpayment());var first=new RefundPaid(3,0,new Refund(UUID.randomUUID(),payment.id(),30000,voucher("refund-1")));UUID op=UUID.randomUUID();var receipt=apply(op,first);assertEquals(20000,balance().overpayment());assertEquals(receipt,apply(op,first));apply(new RefundPaid(4,0,new Refund(UUID.randomUUID(),payment.id(),20000,voucher("refund-2"))));assertEquals(0,balance().overpayment());assertEquals(230000,balance().collected());assertEquals(50000,balance().refunded());assertEquals(1,balance().payments().size());assertEquals(180000,balance().settled());assertEquals(5,fixture.count("finance_money_entry"));assertEquals(0,fixture.store.read(fixture.actor,fixture.owner).qCents());}
 @Test void verifiedOverpaymentIsRetainedAndReferencesCannotBeReused()throws Exception{assessBill();apply(new Collect(1,0,bill,payment(230001,"too-large")));assertEquals(1,balance().overpayment());assertThrows(IllegalStateException.class,()->apply(new Collect(2,0,bill,payment(1000,"too-large"))));assertEquals(230001,balance().collected());}
 @Test void originalCoverageCannotBeAssessedTwice()throws Exception{assessBill();assertThrows(IllegalStateException.class,()->apply(new Assess(1,0,UUID.randomUUID(),new Approval(UUID.randomUUID(),"d".repeat(64),Map.of(line,1000L)))));assertEquals(230000,balance().receivable());}
 @Test void reversalRequiresVerifiedErrorAndDoesNotPretendRefund()throws Exception{assessBill();var payment=payment(100000,"mistyped-receipt");apply(new Collect(1,0,bill,payment));assertThrows(SecurityException.class,()->apply(new Reverse(2,0,payment.id(),UUID.randomUUID(),"REAL_RECEIVED_FUNDS")));apply(new Reverse(2,0,payment.id(),UUID.randomUUID(),"核验实际无到账的错录凭证"));assertEquals(0,balance().collected());assertEquals(0,balance().refunded());assertEquals(1,balance().payments().size());assertThrows(IllegalStateException.class,()->apply(new Reverse(3,0,payment.id(),UUID.randomUUID(),"重复冲正原记录必须拒绝")));}
 @Test void refundRequiresOverpaymentAndCannotEraseLinkedOriginal()throws Exception{assessBill();var payment=payment(230000,"paid");apply(new Collect(1,0,bill,payment));assertThrows(IllegalStateException.class,()->apply(new RefundPaid(2,0,new Refund(UUID.randomUUID(),payment.id(),1,voucher("not-overpaid")))));lowerBill();apply(new RefundPaid(3,0,new Refund(UUID.randomUUID(),payment.id(),10000,voucher("returned"))));assertThrows(IllegalStateException.class,()->apply(new Reverse(4,0,payment.id(),UUID.randomUUID(),"已退款原收款不得冲正")));assertThrows(IllegalStateException.class,()->apply(new RefundPaid(4,0,new Refund(UUID.randomUUID(),payment.id(),50000,voucher("excess")))));assertEquals(40000,balance().overpayment());}
 @Test void sameUuidConcurrentOnceAndCurrentPermissionBeforeReplay()throws Exception{var command=new Assess(0,0,bill,approval);UUID op=UUID.randomUUID();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var jobs=new ArrayList<Future<Receipt>>();for(int n=0;n<6;n++)jobs.add(pool.submit(()->{gate.await();return apply(op,command);}));gate.countDown();var one=jobs.getFirst().get();for(var j:jobs)assertEquals(one,j.get());}assertEquals(1,fixture.count("finance_money_entry"));fixture.allowed.set(false);assertThrows(SecurityException.class,()->apply(op,command));assertThrows(SecurityException.class,()->ledger.operation(fixture.actor,fixture.owner,op));}
 @Test void auditFailureRollsBackAllAndOriginalKeyRecovers()throws Exception{assessBill();long count=fixture.count("finance_operation");try(var db=fixture.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit ADD CONSTRAINT fail_money CHECK(action_name<>'COLLECTION_RECORDED')");}UUID op=UUID.randomUUID();var command=new Collect(1,0,bill,payment(10000,"recover"));assertThrows(Exception.class,()->apply(op,command));assertEquals(0,balance().collected());assertEquals(1,balance().version());assertEquals(count,fixture.count("finance_operation"));assertEquals(0,fixture.count("finance_money_reference"));assertEquals(count,fixture.count("finance_audit"));assertEquals(count,fixture.count("finance_outbox"));try(var db=fixture.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit DROP CONSTRAINT fail_money");}apply(op,command);assertEquals(10000,balance().collected());assertEquals(1,fixture.count("finance_money_reference"));}
 @Test void staleGroupOrAccountVersionAndChangedOriginalParametersFail()throws Exception{assessBill();assertThrows(IllegalStateException.class,()->apply(new Collect(0,0,bill,payment(1000,"old"))));assertThrows(IllegalStateException.class,()->apply(new Collect(1,1,bill,payment(1000,"group-old"))));UUID op=UUID.randomUUID();var c=new Collect(1,0,bill,payment(1000,"right"));var original=apply(op,c);assertEquals(original,ledger.operation(fixture.actor,fixture.owner,op));assertThrows(IllegalStateException.class,()->apply(op,new Collect(2,0,bill,payment(1000,"changed"))));assertEquals(2,fixture.count("finance_money_entry"));}
 @Test void refundRaceWithDifferentKeysCannotOverdraw()throws Exception{assessBill();var payment=payment(230000,"race-paid");apply(new Collect(1,0,bill,payment));lowerBill();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var jobs=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++){int n=i;jobs.add(pool.submit(()->{gate.await();try{apply(new RefundPaid(3,0,new Refund(UUID.randomUUID(),payment.id(),40000,voucher("race-"+n))));return true;}catch(IllegalStateException expected){return false;}}));}gate.countDown();int success=0;for(var j:jobs)if(j.get())success++;assertEquals(1,success);}assertEquals(10000,balance().overpayment());assertEquals(1,balance().refunds().size());}
 @Test void overpaymentCannotAutomaticallySettleAnotherBill()throws Exception{assessBill();var original=payment(230000,"original-bill-paid");apply(new Collect(1,0,bill,original));lowerBill();UUID otherBill=UUID.randomUUID(),otherLine=UUID.randomUUID();apply(new Assess(3,0,otherBill,new Approval(UUID.randomUUID(),"e".repeat(64),Map.of(otherLine,50000L))));assertEquals(50000,balance().overpayment());assertEquals(50000,balance().outstanding());assertEquals(180000,balance().settled());apply(new Collect(4,0,otherBill,new Payment(UUID.randomUUID(),otherBill,50000,voucher("new-bill-new-funds"))));assertEquals(50000,balance().overpayment());assertEquals(0,balance().outstanding());assertThrows(IllegalStateException.class,()->apply(new RefundPaid(5,0,new Refund(UUID.randomUUID(),balance().payments().values().stream().filter(p->p.billId().equals(otherBill)).findFirst().orElseThrow().id(),10000,voucher("wrong-original")))));}
 @Test void canonicalDigestIgnoresMapInsertionOrder(){UUID a=UUID.fromString("00000000-0000-0000-0000-000000000001"),b=UUID.fromString("00000000-0000-0000-0000-000000000002");var first=new LinkedHashMap<UUID,Long>();first.put(a,1L);first.put(b,2L);var second=new LinkedHashMap<UUID,Long>();second.put(b,2L);second.put(a,1L);assertEquals(JdbcMoneyLedger.digest(first),JdbcMoneyLedger.digest(second));} @Test void verifiedMistypedCollectionCanBeReenteredWithSameExternalReference()throws Exception{assessBill();var wrong=payment(100000,"real-bank-reference");apply(new Collect(1,0,bill,wrong));apply(new Reverse(2,0,wrong.id(),UUID.randomUUID(),"已核实金额错录且需要重记真实到账"));var corrected=new Payment(UUID.randomUUID(),bill,80000,voucher("real-bank-reference"),wrong.id());apply(new Collect(3,0,bill,corrected));assertEquals(80000,balance().collected());assertEquals(2,balance().payments().size());assertEquals(0,balance().refunded());assertEquals(2,fixture.count("finance_money_reference"));assertThrows(IllegalStateException.class,()->apply(new Collect(4,0,bill,new Payment(UUID.randomUUID(),bill,1000,voucher("real-bank-reference"),wrong.id()))));} @Test void uncertainRollbackOrCommitDiscardsConnectionWithoutAutoCommitReset()throws Exception{
  for(boolean commitActuallyHappened:List.of(false,true)){
   if(commitActuallyHappened){fixture=new JdbcFeeGroupsTest();fixture.setup();}
   java.sql.Connection physical=fixture.source.getConnection();var resets=new java.util.concurrent.atomic.AtomicInteger();var closes=new java.util.concurrent.atomic.AtomicInteger();var aborts=new java.util.concurrent.atomic.AtomicInteger();
   var proxy=(java.sql.Connection)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{java.sql.Connection.class},(p,m,args)->{switch(m.getName()){case "commit"->{if(commitActuallyHappened)physical.commit();throw new java.sql.SQLException("INJECTED_COMMIT_RESULT_UNKNOWN");}case "rollback"->throw new java.sql.SQLException("INJECTED_ROLLBACK_FAILED");case "abort"->{aborts.incrementAndGet();physical.close();return null;}case "close"->{closes.incrementAndGet();physical.close();return null;}case "setAutoCommit"->{if(Boolean.TRUE.equals(args[0]))resets.incrementAndGet();}}try{return m.invoke(physical,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});
   var faultSource=org.mockito.Mockito.mock(javax.sql.DataSource.class);org.mockito.Mockito.when(faultSource.getConnection()).thenReturn(proxy);
   var authority=new Authority(){public void current(JdbcFeeGroups.Actor a,FeeGroup.Identity o,String action){}public void verify(JdbcFeeGroups.Actor a,FeeGroup.Identity o,UUID op,Command command){if(!commitActuallyHappened)throw new IllegalStateException("ORIGINAL_CURRENT_FACT_REJECTED");}};
   UUID op=UUID.randomUUID();var command=new Assess(0,0,bill,approval);var faultLedger=new JdbcMoneyLedger(faultSource,authority);
   var failure=assertThrows(java.sql.SQLException.class,()->faultLedger.apply(fixture.actor,fixture.owner,op,command));assertEquals("OPERATION_RESULT_UNKNOWN",failure.getMessage());assertNotNull(failure.getCause());assertEquals(1,failure.getCause().getSuppressed().length);assertEquals(1,aborts.get());assertEquals(0,resets.get());assertEquals(0,closes.get());assertTrue(physical.isClosed());
   assertEquals(commitActuallyHappened?1:0,fixture.count("finance_money_entry"));
   var recovered=new JdbcMoneyLedger(fixture.source,new Authority(){public void current(JdbcFeeGroups.Actor a,FeeGroup.Identity o,String action){}public void verify(JdbcFeeGroups.Actor a,FeeGroup.Identity o,UUID id,Command c){}});recovered.apply(fixture.actor,fixture.owner,op,command);assertEquals(1,fixture.count("finance_money_entry"));assertEquals(2,fixture.count("finance_operation"));
  }
 } @Test void tenantWideExternalReferenceConflictRollsBackSecondGroup()throws Exception{assessBill();apply(new Collect(1,0,bill,payment(1000,"tenant-unique-bank-ref")));var other=new FeeGroup.Identity(1,2,UUID.randomUUID());fixture.store.open(fixture.actor,other,UUID.randomUUID());UUID otherBill=UUID.randomUUID();ledger.apply(fixture.actor,other,UUID.randomUUID(),new Assess(0,0,otherBill,new Approval(UUID.randomUUID(),"f".repeat(64),Map.of(UUID.randomUUID(),10000L))));long count=fixture.count("finance_operation");var conflict=assertThrows(IllegalStateException.class,()->ledger.apply(fixture.actor,other,UUID.randomUUID(),new Collect(1,0,otherBill,new Payment(UUID.randomUUID(),otherBill,1000,voucher("tenant-unique-bank-ref")))));assertEquals("MONEY_REFERENCE_CONFLICT",conflict.getMessage());assertEquals(0,ledger.read(fixture.actor,other).collected());assertEquals(1,ledger.read(fixture.actor,other).version());assertEquals(count,fixture.count("finance_operation"));assertEquals(count,fixture.count("finance_audit"));assertEquals(count,fixture.count("finance_outbox"));}}
